namespace CheckoutPricing.Domain;

public static class LoyaltyDiscountPolicy
{
    private const int MinimumSubtotalCents = 3_000;
    private const int CapCents = 2_000;

    public static int LoyaltyPart(int subtotalCents, LoyaltyTier tier) =>
        subtotalCents < MinimumSubtotalCents ? 0 : Math.Min(CapCents, subtotalCents * RatePercent(tier) / 100);

    private static int RatePercent(LoyaltyTier tier) => tier switch
    {
        LoyaltyTier.Bronze => 5,
        LoyaltyTier.Silver => 10,
        LoyaltyTier.Gold => 15,
        LoyaltyTier.Platinum => 20,
        _ => throw new ArgumentOutOfRangeException(nameof(tier), tier, null)
    };
}
EOF
cat > src/CheckoutPricing.Domain/PromoCodePolicy.cs <<'EOF'
namespace CheckoutPricing.Domain;

public static class PromoCodePolicy
{
    private const int WelcomeFiveCents = 500;
    private const int SummerTenCapCents = 1_500;

    public static int Discount(string? promoCode, int subtotalCents, int loyaltyPartCents)
    {
        if (string.Equals(promoCode, "WELCOME5", StringComparison.OrdinalIgnoreCase))
        {
            return WelcomeFiveCents;
        }

        if (string.Equals(promoCode, "SUMMER10", StringComparison.OrdinalIgnoreCase))
        {
            return Math.Min(SummerTenCapCents, (subtotalCents - loyaltyPartCents) / 10);
        }

        return 0;
    }
}
EOF
cat > src/CheckoutPricing.Domain/DiscountPolicy.cs <<'EOF'
namespace CheckoutPricing.Domain;

public static class DiscountPolicy
{
    public static int Discount(int subtotalCents, LoyaltyTier tier, string? promoCode)
    {
        var loyaltyPart = LoyaltyDiscountPolicy.LoyaltyPart(subtotalCents, tier);
        var promoPart = PromoCodePolicy.Discount(promoCode, subtotalCents, loyaltyPart);
        return Math.Min(subtotalCents, loyaltyPart + promoPart);
    }
}
EOF
